INSERT INTO `cursos` (`id_curso`, `id_categoria`, `nome`, `descricao`, `professor`, `id_imagem`, `cargaHoraria`, `situacao`, `dataCriacao`, `dataMudanca`, `percentual_conclusao_certificado`, `temCertificado`) VALUES
(13, 2, 'Formação Intensiva de Instrutores e Professores Kenshydokan', '<p>O curso tem como miss&atilde;o preparar de forma intensiva intrutores e atualizar os professores do Karate Kenshydokan.</p>\r\n<p>Grade Curricular:</p>\r\n<p>Atemi Waza, Nage Waza e Ne Waza</p>', 'Jonas Teixeira de Andrade & Weslley Henrique Vieira Ferraz', '329', 1200, 'aprovado', '2025-09-01', '2025-11-18', 100, 'nao'),
(14, 8, 'Preparação Intensiva para faixas azuis em BJJ', '<p>Neste curso semi presencial teremos aulas tanto presenciais como online para capacitar de forma r&aacute;pida alunos que j&aacute; tem um certo grau de conenhecimento nessa modalidade com foco em no gi (sem kimono).</p>', 'Weslley Henrique Vieira Ferraz', '330', 600, 'aguardando', '2025-09-06', '2025-10-19', 100, 'nao'),
(15, 2, 'Preparatório do Faixa Branca, Azul e Amarela', '<p>Sa&iacute; na frente se preparando para o seu pr&oacute;ximo exame de gradua&ccedil;&atilde;o com mais qualidade</p>', 'Weslley Henrique Vieira Ferraz', '333', 300, 'aprovado', '2025-10-27', '2026-06-24', 100, 'sim'),
(16, 2, 'Curso de Arbitragem Oficial Kenshydokan Jutsu', '<p>Curso online oficial de forma&ccedil;&atilde;o e reciclagem de &aacute;rbitros do estilo Kenshydokan Jutsu. Cobre detalhadamente todas as diretrizes do Livro de Regras Oficiais, incluindo Atemi Waza (luta em p&eacute;), Nage Waza (proje&ccedil;&otilde;es), Ne Waza (solo), infra&ccedil;&otilde;es, crit&eacute;rios de pontua&ccedil;&atilde;o, etiqueta e ritual&iacute;stica. OBS: Conforme a regra oficial, para vencer o combate &eacute; necess&aacute;rio obter 3 Ippons ou a maior pontua&ccedil;&atilde;o ao final do tempo regulamentar.</p>', 'Weslley Henrique Vieira Ferraz', '340', 40, 'aprovado', '2026-06-28', '2026-06-28', 100, 'sim');
